using TaskBoard.Services;
using Xunit;
namespace TaskBoard.Tests;
public sealed class ServiceTests
{
    [Fact] public void Initially_anonymous() { Assert.Null(new TaskBoardService().CurrentUser); }
    [Fact] public async Task Login_authenticates_only_known_credentials() { var s = new TaskBoardService(); Assert.False(await s.LoginAsync("unknown", "wrong")); Assert.Null(s.CurrentUser); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); Assert.Equal("alice@example.test", s.CurrentUser!.Email); }
    [Fact] public async Task Logout_clears_identity_and_denies_read() { var s = new TaskBoardService(); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); s.Logout(); Assert.Null(s.CurrentUser); await Assert.ThrowsAsync<UnauthorizedAccessException>(() => s.ListAsync()); }
    [Fact] public async Task Anonymous_reads_and_mutations_are_denied() { var s = new TaskBoardService(); await Assert.ThrowsAsync<UnauthorizedAccessException>(() => s.ListAsync()); await Assert.ThrowsAsync<UnauthorizedAccessException>(() => s.AddAsync("x")); await Assert.ThrowsAsync<UnauthorizedAccessException>(() => s.SetCompletedAsync(Guid.NewGuid(), true)); await Assert.ThrowsAsync<UnauthorizedAccessException>(() => s.DeleteAsync(Guid.NewGuid())); }
    [Fact] public async Task Add_trims_title_and_allocates_unique_ids() { var s = new TaskBoardService(); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); var a = await s.AddAsync("  Build UI  "); var b = await s.AddAsync("Second"); Assert.Equal("Build UI", a.Title); Assert.False(a.Completed); Assert.NotEqual(Guid.Empty, a.Id); Assert.NotEqual(a.Id, b.Id); Assert.Equal(2, (await s.ListAsync()).Count); }
    [Fact] public async Task Invalid_titles_never_mutate_collection() { var s = new TaskBoardService(); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); await Assert.ThrowsAsync<ArgumentException>(() => s.AddAsync(" ")); await Assert.ThrowsAsync<ArgumentException>(() => s.AddAsync(new string('x', 121))); Assert.Empty(await s.ListAsync()); }
    [Fact] public async Task Filters_are_exact_and_do_not_destroy_data() { var s = new TaskBoardService(); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); var a = await s.AddAsync("A"); var b = await s.AddAsync("B"); Assert.Equal(b with { Completed = true }, await s.SetCompletedAsync(b.Id, true)); Assert.Equal([a], await s.ListAsync(TaskFilter.Active)); Assert.Equal([b with { Completed = true }], await s.ListAsync(TaskFilter.Completed)); Assert.Equal(2, (await s.ListAsync()).Count); }
    [Fact] public async Task Delete_and_unknown_identifiers_follow_contract() { var s = new TaskBoardService(); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); var task = await s.AddAsync("A"); await s.DeleteAsync(task.Id); Assert.Empty(await s.ListAsync()); await Assert.ThrowsAsync<KeyNotFoundException>(() => s.DeleteAsync(task.Id)); await Assert.ThrowsAsync<KeyNotFoundException>(() => s.SetCompletedAsync(task.Id, true)); }
    [Fact] public async Task Sessions_cannot_access_another_users_tasks() { var s = new TaskBoardService(); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); var task = await s.AddAsync("Private"); s.Logout(); Assert.True(await s.LoginAsync("bob@example.test", "Bob!234")); Assert.Empty(await s.ListAsync()); await Assert.ThrowsAsync<KeyNotFoundException>(() => s.SetCompletedAsync(task.Id, true)); await Assert.ThrowsAsync<KeyNotFoundException>(() => s.DeleteAsync(task.Id)); s.Logout(); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); Assert.Equal([task], await s.ListAsync()); }
    [Fact] public async Task Failed_login_clears_existing_identity() { var s = new TaskBoardService(); Assert.True(await s.LoginAsync("alice@example.test", "Alice!234")); Assert.False(await s.LoginAsync("bob@example.test", "wrong")); Assert.Null(s.CurrentUser); await Assert.ThrowsAsync<UnauthorizedAccessException>(() => s.ListAsync()); }
}
